1	/**
2	 * Pure account-state wording shared by the Account drawer, the header status
3	 * note and the empty inbox line. Everything derives from `AccountStatus`
4	 * (connection, sync state and error, initial sync, cached count); nothing here
5	 * invents a state, and pending, failed and unknown stay distinct.
6	 *
7	 * Actions are never gated by the connection (a Gmail command with an expired
8	 * sign-in still runs and fails at the provider), so no text here says actions
9	 * are off. The one standing fact worth saying is about reading: cached mail
10	 * stays readable.
11	 */
12	import type { AccountStatus, MailError } from './ipc/client';
13	
14	/** One plain sentence per typed error. */
15	export function describeMailError(error: MailError): string {
16	  switch (error.kind) {
17	    case 'not_configured':
18	      return 'Gmail is not configured on this device.';
19	    case 'auth_required':
20	      return 'Sign-in is required to continue syncing.';
21	    case 'auth_cancelled':
22	      return 'Sign-in was cancelled.';
23	    case 'auth_failed':
24	      return 'Sign-in failed.';
25	    case 'secrets_unavailable':
26	      return 'Secure credential storage is unavailable.';
27	    case 'network_unavailable':
28	      return 'The network is unavailable.';
29	    case 'rate_limited':
30	      return 'The provider is rate limiting; retrying with backoff.';
31	    case 'provider_unavailable':
32	      return 'The mail provider is temporarily unavailable.';
33	    case 'invalid_provider_response':
34	      return 'The provider returned an unexpected response.';
35	    case 'busy':
36	      return 'A sync is already in progress.';
37	    case 'permission_required':
38	      return 'Google did not grant mailbox-action permission; the account remains read-only.';
39	    case 'provider_rejected':
40	      return 'The provider rejected the mailbox action.';
41	    case 'outcome_unknown':
42	      return 'The provider outcome is unknown; review Activity before retrying.';
43	    case 'read_only':
44	      return 'Gmail is read-only; this action is unavailable.';
45	    case 'storage_unavailable':
46	      return 'Local storage is unavailable.';
47	    case 'not_found':
48	      return 'Not found.';
49	    case 'invalid_request':
50	      return 'Invalid request.';
51	    case 'request_id_conflict':
52	      return 'Conflicting request.';
53	    case 'profile_in_use':
54	      return 'The profile is in use by another window.';
55	    default:
56	      return 'Unknown error.';
57	  }
58	}
59	
60	export type AccountNoticeKind =
61	  | 'not_configured' | 'disconnected' | 'auth_required' | 'authenticating'
62	  | 'syncing' | 'offline' | 'sync_failed';
63	export type AccountNoticeAction = 'connect' | 'sync' | 'cancel';
64	
65	/** The header note: terse visible text, the full fact in `title`. */
66	export interface AccountNotice {
67	  kind: AccountNoticeKind;
68	  /** Visible words. */
69	  text: string;
70	  /**
71	   * Self-contained sentence(s): the hover title and the visually hidden text.
72	   * It never contains a ticking count, so it can be announced once.
73	   */
74	  title: string;
75	  action: AccountNoticeAction | null;
76	  actionLabel: string;
77	  tone: 'neutral' | 'warning' | 'danger';
78	}
79	
80	/** Connection states that replace the older read-only hint in the header. */
81	export const CONNECTION_NOTICE_KINDS: readonly AccountNoticeKind[] = ['not_configured', 'disconnected', 'auth_required', 'authenticating'];
82	
83	/** Null in fixture mode, without a status, and while connected and idle. */
84	export function accountNotice(status: AccountStatus | null): AccountNotice | null {
85	  if (!status || status.mode !== 'gmail') return null;
86	  const { sync } = status;
87	  const cached = sync.cachedConversations;
88	  switch (status.connection) {
89	    case 'not_configured':
90	      return {
91	        kind: 'not_configured', text: 'Gmail not configured', action: null, actionLabel: '', tone: 'neutral',
92	        title: 'Gmail is not configured on this device. Connecting is unavailable.',
93	      };
94	    case 'disconnected':
95	      return {
96	        kind: 'disconnected', text: 'Not connected', action: 'connect', actionLabel: 'Connect', tone: 'neutral',
97	        title: cached > 0
98	          ? 'Not connected to Gmail. Cached mail stays readable; new mail will not sync until you connect.'
99	          : 'Not connected to Gmail. Connect to load and sync mail.',
100	      };
101	    case 'auth_required':
102	      return {
103	        kind: 'auth_required', text: 'Sign-in expired', action: 'connect', actionLabel: 'Sign in', tone: 'warning',
104	        title: 'Sign-in expired. Cached mail stays readable; new mail will not sync until you sign in.',
105	      };
106	    case 'authenticating':
107	      return {
108	        kind: 'authenticating', text: 'Finish sign-in in your browser', action: 'cancel', actionLabel: 'Cancel', tone: 'neutral',
109	        title: 'Gmail sign-in is waiting for your browser. Cancel stops it.',
110	      };
111	    case 'connected':
112	      break;
113	  }
114	  if (sync.state === 'error') {
115	    const firstSync = sync.initialSyncComplete ? '' : ` · ${cached} cached`;
116	    const cause = sync.error ? `${describeMailError(sync.error)} ` : '';
117	    if (sync.error?.kind === 'network_unavailable') {
118	      return {
119	        kind: 'offline', text: `Offline${firstSync}`, action: 'sync', actionLabel: 'Retry', tone: 'warning',
120	        title: `Offline. ${cause}Cached mail stays readable; new mail has not synced.`,
121	      };
122	    }
123	    return {
124	      kind: 'sync_failed', text: `Sync failed${firstSync}`, action: 'sync', actionLabel: 'Retry', tone: 'danger',
125	      title: `Sync failed. ${cause}Cached mail stays readable; new mail has not synced.`,
126	    };
127	  }
128	  if (sync.state === 'syncing') {
129	    return sync.initialSyncComplete
130	      ? { kind: 'syncing', text: 'Syncing…', title: 'Syncing mail. Cached mail stays readable.', action: null, actionLabel: '', tone: 'neutral' }
131	      : { kind: 'syncing', text: `Syncing first mail · ${cached} cached`, title: 'Syncing first mail. Cached mail stays readable.', action: null, actionLabel: '', tone: 'neutral' };
132	  }
133	  return null;
134	}
135	
136	export const INBOX_EMPTY_RECOVERABLE = 'No conversations are currently in the inbox. Archived conversations stay recoverable from Activity.';
137	/** Gmail without mailbox actions: Activity offers no Mark not done there, so it is not promised. */
138	export const INBOX_EMPTY_READ_ONLY = 'No conversations in the cached inbox.';
139	
140	export type InboxEmptyKind =
141	  | 'not_configured' | 'disconnected' | 'auth_required' | 'authenticating'
142	  | 'syncing' | 'sync_error' | 'sync_unfinished' | 'empty';
143	export type InboxEmptyAction = 'connect' | 'sync' | 'cancel' | 'account';
144	
145	export interface InboxEmpty {
146	  kind: InboxEmptyKind;
147	  text: string;
148	  action: InboxEmptyAction | null;
149	  actionLabel: string;
150	}
151	
152	/**
153	 * What a plain, zero-row Gmail inbox really means. Null outside Gmail mode (the
154	 * caller keeps the fixture sentence). Only a connected, fully synced account
155	 * gets the real "empty" text.
156	 */
157	export function inboxEmptyState(status: AccountStatus | null): InboxEmpty | null {
158	  if (!status || status.mode !== 'gmail') return null;
159	  const { sync } = status;
160	  switch (status.connection) {
161	    case 'not_configured':
162	      return { kind: 'not_configured', text: 'Gmail is not configured on this device.', action: 'account', actionLabel: 'Account' };
163	    case 'disconnected':
164	      return { kind: 'disconnected', text: 'Not connected.', action: 'connect', actionLabel: 'Connect Gmail' };
165	    case 'auth_required':
166	      return { kind: 'auth_required', text: 'Sign-in expired.', action: 'connect', actionLabel: 'Sign in again' };
167	    case 'authenticating':
168	      return { kind: 'authenticating', text: 'Finish sign-in in your browser.', action: 'cancel', actionLabel: 'Cancel' };
169	    case 'connected':
170	      break;
171	  }
172	  if (sync.state === 'error') {
173	    const cause = sync.error ? describeMailError(sync.error) : 'Unknown error.';
174	    return { kind: 'sync_error', text: `Sync failed: ${cause}`, action: 'sync', actionLabel: 'Retry' };
175	  }
176	  if (!sync.initialSyncComplete) {
177	    return sync.state === 'syncing'
178	      ? { kind: 'syncing', text: `Syncing first mail… ${sync.cachedConversations} cached.`, action: null, actionLabel: '' }
179	      : { kind: 'sync_unfinished', text: 'Initial sync has not finished.', action: 'sync', actionLabel: 'Sync now' };
180	  }
181	  return {
182	    kind: 'empty',
183	    text: status.mutationAccess === 'enabled' ? INBOX_EMPTY_RECOVERABLE : INBOX_EMPTY_READ_ONLY,
184	    action: null,
185	    actionLabel: '',
186	  };
187	}
