}

/* Active list filter, in words beside the tabs. */
.header-filter {
  flex: 0 0 auto;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.header-trail {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

/* Compact one-line notes; they give up width before the glyphs do. */
.header-note {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 12px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
