}

.list-more {
  flex: 0 0 auto;
  align-self: flex-start;
.status-applying {
  font-style: italic;
}

.status-outcome_unknown,
.activity-warning,
.activity-error,
.account-action-error {
  color: var(--warning);
}

.activity-warning,
