let wrapper: VueWrapper | null = null;
afterEach(() => { wrapper?.unmount(); wrapper = null; });

function status(patch: {
  connection?: ConnectionState;
  mutationAccess?: MutationAccess;
  sync?: Partial<SyncInfo>;
  account?: AccountStatus['account'];
} = {}): AccountStatus {
  return {
    mode: 'gmail',
