p='src/App.vue'
s=open(p).read()
old="""            <span aria-hidden="true">{{ statusNotice.text }}</span><span class="visually-hidden">{{ statusNotice.title }}</span>
            <template v-if="headerAction && (headerAction.action === 'account' || accountActionsIdle)"><span aria-hidden="true"> · </span>"""
new="""            <span class="note-text" aria-hidden="true">{{ statusNotice.text }}</span><span class="visually-hidden">{{ statusNotice.title }}</span>
            <template v-if="headerAction && (headerAction.action === 'account' || accountActionsIdle)"><span class="note-sep" aria-hidden="true">·</span>"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
p='src/assets/style.css'
s=open(p).read()
s=s.replace(""".header-note.account-status-note {
  flex-shrink: 1;
}""",""".header-note.account-status-note {
  flex-shrink: 1;
  display: flex;
  align-items: baseline;
}

/* Only the words ellipsize; the action link never clips (the empty line and the drawer are not always in view). */
.account-status-note .note-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-status-note .note-sep {
  flex: none;
  padding: 0 0.35em;
}

.account-status-note .header-link {
  flex: none;
}""")
open(p,'w').write(s)
EOF
sleep 1

